import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`roofing-audit`,heroTitle:`Audit your roofing business in minutes`,heroSubtitle:`Perplexity Computer audits your local presence, benchmarks top roofers nearby, and turns the gaps into a lead-generation plan.`,inputUrlCta:`Audit my roofing business`,inputUrlPlaceholder:`yourroofingcompany.com`,inputUrlPrefill:`Go to {url} and run a full growth audit for this roofing business. (1) Review the website, Google Business Profile, reviews, trust signals, service pages, and contact flow. (2) Analyze local search performance for high-intent keywords like "roof repair near me" and "roof replacement [city]" and identify where the business is missing visibility. (3) Benchmark against top local roofing companies on review strength, service positioning, storm-season messaging, local ads, and proof of quality. (4) Call out the gaps hurting leads, trust, and local conversion. (5) Deliver a prioritized plan with service-page rewrites, review-generation ideas, seasonal marketing actions, and Google Local Services Ads recommendations.`,heroOverlaySteps:[`Auditing the website, local listings, reviews, and trust signals for roofing leads`,`Benchmarking top roofers nearby on reviews, visibility, and service positioning`,`Finding the keyword, proof, and conversion gaps that are costing estimates`,`Growth plan with page rewrites, review system, and seasonal marketing priorities ready to use`],generatingSteps:[`Visiting {url} to review the site, local listings, and current lead-capture setup`,`Designing an agent to benchmark top roofing competitors across visibility and trust signals`,`Configuring local search, review, and page rewrite recommendations for higher lead quality`,`Packaging the work into a prioritized roofing growth plan with seasonal actions`],featureSectionTitle:`From scattered local presence to a clearer roofing growth plan`,featureCardTitles:[`Connects to your local ops workflow`,`Fixes tied to more estimates`],featureCardDescriptions:[`Computer splits the work into site review, local search analysis, competitor research, and trust-signal planning so the final audit stays specific to roofing demand.`,`Docs, Sheets, CRM notes, and planning tools can stay connected so service-page updates, review asks, and seasonal campaigns stay organized.`,`Service-page rewrites. Review generation ideas. Local search fixes. Seasonal marketing actions. Computer gives your team the specific changes most likely to drive more roofing leads.`],capabilitySectionTitle:`Your roofing growth analyst, on autopilot`,capabilitySectionSubtitle:`Paste your site, step away, and come back to the local fixes most likely to win more leads.`,capabilityCards:[{title:`Local Presence Audit`,description:`Computer can review your site, Google Business Profile, reviews, and trust signals to show where local buyers lose confidence.`},{title:`Keyword Gap Analysis`,description:`Computer can identify the roofing terms and service combinations where competitors own visibility and your business does not.`},{title:`Competitor Benchmarking`,description:`Computer can compare your business against strong local roofers on proof, positioning, response speed, and seasonal messaging.`},{title:`Connect Your Tools`,description:`Computer can organize audit findings, page rewrites, and campaign ideas across Docs, Sheets, and planning tools.`},{title:`Lead Conversion Fixes`,description:`Computer can recommend the trust and contact-flow changes most likely to improve estimate requests from local visitors.`},{title:`Seasonal Follow-Up`,description:`Computer can revisit the market later and suggest new actions as storm season, review volume, or local competition changes.`}]});export{t as default};
